	.section	.text._render_scaled_packed4_asm,"ax",@progbits
	.globl	_render_scaled_packed4_asm
	.type	_render_scaled_packed4_asm,@function
_render_scaled_packed4_asm:
	push	ix
	ld	ix, 0
	add	ix, sp
	push	iy
	ld	hl, (ix + 6)
	ld	de, (0xE30014)
	push	hl
	ld	hl, 7680
	add	hl, de
	ex	de, hl
	pop	hl
	ld	a, 96
.Lp4row:
	push	af
	push	hl
	ld	b, 80
.Lp4pass1:
	ld	a, (hl)
	inc	hl
	ld	c, a
	and	0F0h
	rrca
	rrca
	rrca
	rrca
	ld	(de), a
	inc	de
	ld	(de), a
	inc	de
	ld	a, c
	and	0Fh
	ld	(de), a
	inc	de
	ld	(de), a
	inc	de
	djnz	.Lp4pass1
	pop	hl
	ld	b, 80
.Lp4pass2:
	ld	a, (hl)
	inc	hl
	ld	c, a
	and	0F0h
	rrca
	rrca
	rrca
	rrca
	ld	(de), a
	inc	de
	ld	(de), a
	inc	de
	ld	a, c
	and	0Fh
	ld	(de), a
	inc	de
	ld	(de), a
	inc	de
	djnz	.Lp4pass2
	pop	af
	dec	a
	jr	nz, .Lp4row
	pop	iy
	pop	ix
	ret
.Lp4end:
	.size	_render_scaled_packed4_asm, .Lp4end-_render_scaled_packed4_asm

; Experimental Packed4 renderer A: expand each packed byte once and write
; both destination rows. Kept separate until physical timing proves a win:
; indexed IY stores may cost more than the saved nibble operations.
	.section	.text._render_scaled_packed4_dual_asm,"ax",@progbits
	.globl	_render_scaled_packed4_dual_asm
	.type	_render_scaled_packed4_dual_asm,@function
_render_scaled_packed4_dual_asm:
	push	ix
	ld	ix, 0
	add	ix, sp
	push	iy
	ld	hl, (ix + 6)
	ld	de, (0xE30014)
	push	hl
	ld	hl, 7680
	add	hl, de
	ex	de, hl
	pop	hl
	ld	a, 96
.Lp4dualrow:
	push	af
	push	de
	pop	iy
	ld	bc, 320
	add	iy, bc
	ld	b, 80
.Lp4dualbyte:
	ld	a, (hl)
	inc	hl
	ld	c, a
	and	0F0h
	rrca
	rrca
	rrca
	rrca
	ld	(de), a
	inc	de
	ld	(de), a
	inc	de
	ld	(iy + 0), a
	inc	iy
	ld	(iy + 0), a
	inc	iy
	ld	a, c
	and	0Fh
